#!/usr/bin/env python3
"""
Secure sensitive-data vault.

Stores credit card numbers and personal information in an encrypted file.
Key derivation: PBKDF2-HMAC-SHA256 (salted, high iteration count).
Encryption: HMAC-SHA256 keystream (per-save random nonce) with
encrypt-then-MAC authentication using HMAC-SHA256.
Only the Python standard library is used.
"""

import getpass
import hashlib
import hmac
import json
import os
import secrets
import sys
import uuid
from datetime import datetime, timezone

PBKDF2_ITERATIONS = 310_000
SALT_SIZE = 16
NONCE_SIZE = 16
TAG_SIZE = 32
VAULT_VERSION = 1
RECORD_KINDS = ("credit_card", "personal")


def derive_keys(password, salt):
    if not isinstance(password, str) or not password:
        raise ValueError("Password must be a non-empty string.")
    material = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt, PBKDF2_ITERATIONS, dklen=64
    )
    return material[:32], material[32:]


def _keystream(enc_key, nonce, length):
    out = bytearray()
    counter = 0
    while len(out) < length:
        block = hmac.new(
            enc_key, nonce + counter.to_bytes(8, "big"), hashlib.sha256
        ).digest()
        out.extend(block)
        counter += 1
    return bytes(out[:length])


def _xor(a, b):
    return bytes(x ^ y for x, y in zip(a, b))


def encrypt_bytes(enc_key, mac_key, plaintext):
    nonce = os.urandom(NONCE_SIZE)
    ciphertext = _xor(plaintext, _keystream(enc_key, nonce, len(plaintext)))
    tag = hmac.new(mac_key, nonce + ciphertext, hashlib.sha256).digest()
    return nonce + ciphertext + tag


def decrypt_bytes(enc_key, mac_key, blob):
    if len(blob) < NONCE_SIZE + TAG_SIZE:
        raise ValueError("Encrypted data is truncated or corrupt.")
    nonce = blob[:NONCE_SIZE]
    ciphertext = blob[NONCE_SIZE:-TAG_SIZE]
    tag = blob[-TAG_SIZE:]
    expected = hmac.new(mac_key, nonce + ciphertext, hashlib.sha256).digest()
    if not hmac.compare_digest(tag, expected):
        raise ValueError("Authentication failed: wrong password or tampered data.")
    return _xor(ciphertext, _keystream(enc_key, nonce, len(ciphertext)))


def luhn_valid(card_number):
    digits = [int(c) for c in card_number if c.isdigit()]
    if len(digits) < 12 or len(digits) > 19:
        return False
    checksum = 0
    parity = len(digits) % 2
    for index, digit in enumerate(digits):
        if index % 2 == parity:
            digit *= 2
            if digit > 9:
                digit -= 9
        checksum += digit
    return checksum % 10 == 0


def normalize_card_number(card_number):
    cleaned = "".join(ch for ch in card_number if ch.isdigit())
    if not luhn_valid(cleaned):
        raise ValueError("Invalid credit card number.")
    return cleaned


def mask_value(value, keep=4):
    if not value:
        return ""
    if len(value) <= keep:
        return "*" * len(value)
    return "*" * (len(value) - keep) + value[-keep:]


def read_vault_file(path):
    with open(path, "r", encoding="utf-8") as fh:
        container = json.load(fh)
    if container.get("version") != VAULT_VERSION:
        raise ValueError("Unsupported vault version.")
    return bytes.fromhex(container["salt"]), bytes.fromhex(container["data"])


def write_vault_file(path, salt, blob):
    container = {
        "version": VAULT_VERSION,
        "salt": salt.hex(),
        "data": blob.hex(),
    }
    tmp_path = path + ".tmp"
    fd = os.open(tmp_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as fh:
        json.dump(container, fh)
    os.replace(tmp_path, path)


def create_vault(path, password):
    if os.path.exists(path):
        raise FileExistsError("Vault already exists.")
    salt = secrets.token_bytes(SALT_SIZE)
    enc_key, mac_key = derive_keys(password, salt)
    blob = encrypt_bytes(enc_key, mac_key, json.dumps({}).encode("utf-8"))
    write_vault_file(path, salt, blob)
    return {}


def open_vault(path, password):
    salt, blob = read_vault_file(path)
    enc_key, mac_key = derive_keys(password, salt)
    plaintext = decrypt_bytes(enc_key, mac_key, blob)
    return json.loads(plaintext.decode("utf-8"))


def save_vault(path, password, records):
    salt = secrets.token_bytes(SALT_SIZE)
    enc_key, mac_key = derive_keys(password, salt)
    payload = json.dumps(records, sort_keys=True).encode("utf-8")
    blob = encrypt_bytes(enc_key, mac_key, payload)
    write_vault_file(path, salt, blob)


def add_credit_card(records, label, holder, card_number, expiry, cvv):
    if not label or not holder:
        raise ValueError("Label and cardholder name are required.")
    cleaned = normalize_card_number(card_number)
    if not (len(cvv) in (3, 4) and cvv.isdigit()):
        raise ValueError("CVV must be 3 or 4 digits.")
    record_id = str(uuid.uuid4())
    records[record_id] = {
        "kind": "credit_card",
        "label": label,
        "holder": holder,
        "number": cleaned,
        "expiry": expiry,
        "cvv": cvv,
        "created": datetime.now(timezone.utc).isoformat(),
    }
    return record_id


def add_personal_info(records, label, full_name, dob, ssn, address, phone, email):
    if not label or not full_name:
        raise ValueError("Label and full name are required.")
    record_id = str(uuid.uuid4())
    records[record_id] = {
        "kind": "personal",
        "label": label,
        "full_name": full_name,
        "date_of_birth": dob,
        "ssn": ssn,
        "address": address,
        "phone": phone,
        "email": email,
        "created": datetime.now(timezone.utc).isoformat(),
    }
    return record_id


def delete_record(records, record_id):
    if record_id not in records:
        raise KeyError("No such record.")
    del records[record_id]
    return records


